{"content":"import 'dart:math';

import 'package:flutter_agent_harness/src/cli/ansi_markdown.dart';

final _rng = Random(1496);

const _words = [
  'lorem', 'ipsum', 'dolor', 'sit', 'amet', 'consectetur', 'adipiscing',
  'elit', 'sed', 'do', 'eiusmod', 'tempor', 'incididunt', 'ut', 'labore',
  'et', 'dolore', 'magna', 'aliqua',
];

String asciiProse(int cells) {
  final buf = StringBuffer();
  while (buf.length < cells) {
    buf.write(_words[_rng.nextInt(_words.length)]);
    buf.write(' ');
  }
  return buf.toString().substring(0, cells);
}

double medianWrapMs(String line, int width, {int runs = 5}) {
  wrapAnsiLine(line, width);
  final times = List<double>.filled(runs, 0);
  for (var i = 0; i < runs; i++) {
    final sw = Stopwatch()..start();
    wrapAnsiLine(line, width);
    sw.stop();
    times[i] = sw.elapsedMicroseconds / 1000.0;
  }
  times.sort();
  return times[runs ~/ 2];
}

void main() {
  for (final base in [100000, 200000, 400000]) {
    final small = medianWrapMs(asciiProse(base), 80);
    final doubled = medianWrapMs(asciiProse(base * 2), 80);
    final ratio = doubled / small;
    print(
      'base=$base: small=${small.toStringAsFixed(2)}ms '
      'doubled=${doubled.toStringAsFixed(2)}ms ratio=${ratio.toStringAsFixed(2)}x '
      '${ratio < 3.2 ? 'PASS' : 'FAIL'}',
    );
  }
}
